scripts.iterate_map:
def solve(inputs: dict) -> float:
    x = inputs['X']
    c = inputs['C']
    mod = inputs['MOD']
    k = inputs['K']

    # Iterate the map k times
    for _ in range(k):
        x = (x * x + c) % mod

    return float(x)

